export const privacy:Record<Difficulty,Question[]>={
 easy:[
 q('A equipe quer publicar uma foto do escritório. Um crachá e uma tela com clientes aparecem ao fundo. O que fazer?','The team wants to post an office photo. A badge and a screen showing customers are visible. What should you do?',[['Publicar porque são apenas detalhes','Post it because these are just details'],['Remover os dados visíveis e verificar autorização antes de publicar','Remove visible data and check authorization before posting'],['Marcar os clientes para dar contexto','Tag the customers to provide context']],1,['Fotos podem expor nomes, identificadores e dados de clientes. Revise a imagem e o contexto antes de compartilhar.','Photos can expose names, identifiers and customer data. Review the image and context before sharing.'],['Observe também o que está no fundo da imagem.','Look at what is in the background too.']),
 q('Um formulário de newsletter pede CPF, endereço residencial e data de nascimento. Qual pergunta fazer?','A newsletter form asks for an ID number, home address and date of birth. What should you ask?',[['Esses dados são necessários para enviar a newsletter?','Are these data necessary to send the newsletter?'],['Como posso adicionar ainda mais campos?','How can I add even more fields?'],['Posso tornar todos os campos públicos?','Can I make all fields public?']],0,['Colete apenas dados necessários para uma finalidade clara. Mais dados não significam um serviço melhor.','Collect only data needed for a clear purpose. More data does not mean a better service.'],['Compare cada campo com a finalidade do formulário.','Compare every field with the purpose of the form.']),
 q('Você quer compartilhar um relatório que contém dados pessoais. Qual opção protege melhor os dados?','You need to share a report containing personal data. Which option protects them best?',[['Enviar em um grupo público','Send it to a public group'],['Criar um link aberto para qualquer pessoa','Create a link anyone can access'],['Usar o canal autorizado e dar acesso apenas a quem precisa','Use the authorized channel and grant access only to those who need it']],2,['Limitar o acesso reduz exposição desnecessária. Use os canais e as regras da organização.','Limiting access reduces unnecessary exposure. Use the organization’s channels and rules.'],['Quem realmente precisa receber o relatório?','Who actually needs the report?'])],
 normal:[
 q('Uma planilha de clientes foi compartilhada com a pessoa errada. Qual é a melhor primeira resposta?','A customer spreadsheet was shared with the wrong person. What is the best initial response?',[['Revogar o acesso possível e avisar a equipe responsável sem esconder o ocorrido','Revoke access where possible and notify the responsible team without hiding the event'],['Esperar para ver se alguém percebe','Wait to see whether anyone notices'],['Apagar todas as evidências da conversa','Delete all evidence of the conversation']],0,['Contenha a exposição e reporte prontamente. A equipe responsável avalia impacto e obrigações aplicáveis.','Contain the exposure and report promptly. The responsible team assesses impact and applicable obligations.'],['Reduza a exposição e permita uma avaliação informada.','Reduce exposure and enable an informed assessment.']),
 q('Um aplicativo tem consentimento para enviar alertas. Isso autoriza vender a lista de usuários?','An app has consent to send alerts. Does that authorize selling its user list?',[['Sim, qualquer consentimento serve para tudo','Yes, any consent covers everything'],['Não; um propósito não autoriza automaticamente outro uso','No; one purpose does not automatically authorize another use'],['Sim, se a lista tiver menos de mil pessoas','Yes, if the list has fewer than a thousand people']],1,['A finalidade precisa ser clara. Consentimento não é uma autorização genérica; o uso deve respeitar a base e o contexto aplicáveis.','The purpose must be clear. Consent is not a blanket authorization; use must respect the applicable basis and context.'],['Uma autorização deve ser entendida no seu contexto.','An authorization must be understood in its context.']),
 q('Você apagou o nome de um relatório, mas manteve e-mail e número de documento. O relatório ficou anônimo?','You removed names from a report but kept email addresses and ID numbers. Is it anonymous?',[['Sim, porque não há nomes','Yes, because there are no names'],['Sim, se estiver em PDF','Yes, if it is a PDF'],['Não; outros identificadores ainda podem revelar a pessoa','No; other identifiers can still reveal the person']],2,['Anonimização exige avaliar a possibilidade de identificação com os dados restantes e outras informações. Remover nomes não basta.','Anonymization requires assessing identification from the remaining data and other information. Removing names is not enough.'],['Quais campos ainda permitem identificar alguém?','Which fields can still identify someone?'])],
 hard:[
 q('Você recebe um pedido para apagar dados pessoais. Qual é a abordagem adequada?','You receive a request to erase personal data. What is the appropriate approach?',[['Apagar tudo imediatamente, incluindo registros necessários','Immediately erase everything, including required records'],['Recusar todos os pedidos automaticamente','Automatically reject every request'],['Encaminhar ao fluxo de privacidade, verificar identidade proporcionalmente e avaliar obrigações de retenção','Use the privacy process, verify identity proportionately and assess retention obligations']],2,['Pedidos de titulares exigem avaliação contextual. Evite coletar mais dados do que o necessário para verificar o pedido.','Data subject requests require contextual assessment. Avoid collecting more data than needed to verify the request.'],['Considere direitos, finalidade e obrigações aplicáveis.','Consider rights, purpose and applicable obligations.']),
 q('Uma base usa códigos no lugar dos nomes. A chave que liga códigos a pessoas ainda existe. Como tratá-la?','A dataset uses codes instead of names. The key linking codes to people still exists. How should it be treated?',[['Como dado que ainda pode ser associado a pessoas; proteger também a chave','As data that can still be linked to people; protect the key too'],['Como base automaticamente anônima e pública','As an automatically anonymous and public dataset'],['Como dado sem qualquer risco de identificação','As data with no identification risk']],0,['Substituir identificadores por códigos reduz exposição, mas a ligação pode continuar possível. Proteja a base e a chave separadamente.','Replacing identifiers with codes reduces exposure, but linkage may remain possible. Protect the dataset and key separately.'],['É possível refazer a ligação com a identidade?','Can the identity link be reconstructed?']),
 q('Um painel interno reúne salários, dados de saúde e e-mails. Como reduzir o risco?','An internal dashboard combines salaries, health data and emails. How can you reduce risk?',[['Dar acesso a toda a empresa para simplificar','Grant access to the whole company for simplicity'],['Limitar dados e acessos por função, registrar acessos e revisar a necessidade','Limit data and access by role, log access and review necessity'],['Usar um endereço difícil de adivinhar como única proteção','Use a hard-to-guess address as the only protection']],1,['Dados sensíveis e agregação aumentam o impacto de exposição. Minimize os dados e aplique controles de acesso apropriados.','Sensitive data and aggregation increase exposure impact. Minimize data and apply appropriate access controls.'],['Um endereço secreto não substitui autorização.','A secret address does not replace authorization.'])]
};
export const malware:Record<Difficulty,Question[]>={
 easy:[
 q('Um anúncio diz que seu computador tem vírus e exige instalar um programa. O que fazer?','An ad claims your computer has viruses and demands software installation. What should you do?',[['Fechar a página e verificar pelo aplicativo de segurança já instalado','Close the page and check with the security app already installed'],['Instalar o programa do anúncio','Install the program from the ad'],['Telefonar para o número do anúncio e conceder acesso remoto','Call the ad’s number and grant remote access']],0,['Alertas em páginas podem ser golpes. Use ferramentas conhecidas e canais oficiais; não conceda acesso por um anúncio.','Warnings on web pages may be scams. Use known tools and official channels; do not grant access through an ad.'],['Quem está emitindo o alerta: o sistema ou uma página?','Who is issuing the warning: the system or a web page?']),
 q('Seus arquivos ganharam uma extensão estranha e uma mensagem pede resgate. Qual é a prioridade?','Your files have a strange extension and a message demands ransom. What is the priority?',[['Conectar o disco de backup para copiar tudo','Connect the backup drive and copy everything'],['Desconectar da rede e avisar a equipe de segurança por um canal confiável','Disconnect from the network and notify security through a trusted channel'],['Enviar o arquivo suspeito aos colegas para testar','Send the suspicious file to colleagues for testing']],1,['Suspeita de ransomware exige contenção e resposta coordenada. Não exponha backups ou outros dispositivos ao sistema suspeito.','Suspected ransomware requires containment and coordinated response. Do not expose backups or other devices to the suspect system.'],['Primeiro, evite que o problema alcance outros recursos.','First, prevent the problem from reaching other resources.']),
 q('Como reduzir a chance de uma infecção por malware?','How can you reduce the chance of malware infection?',[['Desativar atualizações para não mudar o computador','Disable updates so the computer does not change'],['Confiar em qualquer arquivo com nome conhecido','Trust any file with a familiar name'],['Atualizar sistema e aplicativos, usar proteção e verificar a origem dos arquivos','Update the OS and apps, use protection and verify file sources']],2,['Atualizações, proteção e cautela são camadas complementares. Nenhuma delas garante risco zero.','Updates, protection and caution are complementary layers. None guarantees zero risk.'],['Combine prevenção técnica e decisões cuidadosas.','Combine technical prevention with careful decisions.'])],
 normal:[
 q('Um documento pede para habilitar macros para mostrar uma fatura inesperada. Como agir?','A document asks you to enable macros to show an unexpected invoice. What should you do?',[['Habilitar para descobrir o valor','Enable them to see the amount'],['Renomear o arquivo e tentar de novo','Rename the file and try again'],['Não habilitar; verificar a origem e reportar pelo canal da empresa','Do not enable them; verify the source and report through the company channel']],2,['Macros executam ações no documento e podem ser abusadas. Um pedido inesperado para habilitá-las exige verificação.','Macros execute actions in a document and can be abused. An unexpected request to enable them requires verification.'],['Para ler uma fatura, você deveria precisar executar código?','Should reading an invoice require running code?']),
 q('O antivírus colocou um arquivo em quarentena. O fornecedor pede que você libere sem verificar. Qual é a melhor ação?','Antivirus quarantined a file. A supplier asks you to release it without checking. What is the best action?',[['Manter a quarentena e pedir análise da equipe responsável','Keep quarantine and request analysis by the responsible team'],['Liberar e desativar o antivírus','Release it and disable antivirus'],['Executar em todos os computadores para comparar','Run it on every computer to compare']],0,['Uma detecção pode precisar de análise, mas liberar sem verificação elimina uma proteção importante.','A detection may need analysis, but releasing it without verification removes important protection.'],['Uma alegação do fornecedor não substitui análise.','A supplier’s claim does not replace analysis.']),
 q('Um notebook suspeito está isolado. Quando conectar o backup de produção?','A suspect laptop is isolated. When should you connect the production backup?',[['Imediatamente, antes de investigar','Immediately, before investigating'],['Após preparar um ambiente confiável e validar a recuperação com a equipe responsável','After preparing a trusted environment and validating recovery with the responsible team'],['Sempre, pois backups não podem ser atacados','Always, because backups cannot be attacked']],1,['Backups acessíveis podem ser afetados pelo mesmo incidente. Recupere em ambiente confiável depois de avaliar o comprometimento.','Accessible backups may be affected by the same incident. Recover in a trusted environment after assessing compromise.'],['Proteja a cópia que permitirá recuperar o serviço.','Protect the copy that will allow service recovery.'])],
 hard:[
 q('Há alerta de ransomware numa estação. Qual sequência preserva a resposta coordenada?','There is a ransomware alert on a workstation. Which sequence supports coordinated response?',[['Conter o acesso à rede, acionar a equipe e preservar evidências conforme o plano','Contain network access, involve the team and preserve evidence according to the plan'],['Reinstalar tudo imediatamente, sem registro','Immediately reinstall everything without records'],['Apagar os logs para liberar espaço','Delete logs to free space']],0,['Contenção, comunicação e preservação de evidências ajudam a avaliar extensão e origem. Recuperação deve seguir o plano de resposta.','Containment, communication and evidence preservation help assess scope and origin. Recovery should follow the response plan.'],['Conter o impacto não significa apagar o que ocorreu.','Containing impact does not mean erasing what happened.']),
 q('Depois de restaurar arquivos, a equipe quer encerrar o incidente sem investigar o acesso inicial. Qual problema permanece?','After restoring files, the team wants to close the incident without investigating initial access. What problem remains?',[['Nenhum, pois os arquivos foram recuperados','None, because files were recovered'],['O acesso ou a falha que permitiu o incidente pode continuar presente','The access or flaw that enabled the incident may remain'],['Investigar sempre recria o malware','Investigation always recreates malware']],1,['Restaurar dados não remove automaticamente credenciais comprometidas, persistência ou vulnerabilidades. Corrija as causas antes do retorno.','Restoring data does not automatically remove compromised credentials, persistence or vulnerabilities. Address causes before returning.'],['Recuperar o efeito não elimina necessariamente a causa.','Recovering from the effect does not necessarily remove the cause.']),
 q('Uma ferramenta não encontrou malware. Isso comprova que o sistema está limpo?','A tool did not find malware. Does that prove the system is clean?',[['Sim, qualquer resultado negativo é conclusivo','Yes, any negative result is conclusive'],['Sim, se a análise levou mais de uma hora','Yes, if the scan lasted over an hour'],['Não; correlacione alertas, registros e contexto com a equipe responsável','No; correlate alerts, records and context with the responsible team']],2,['Ferramentas têm limites de cobertura. Ausência de detecção não prova ausência de comprometimento.','Tools have coverage limits. No detection does not prove no compromise.'],['Uma única fonte não conta toda a história.','A single source does not tell the whole story.'])]
};
export const mobile:Record<Difficulty,Question[]>={
 easy:[
 q('Um aplicativo de lanterna pede contatos e localização permanente. Qual é a melhor decisão?','A flashlight app asks for contacts and continuous location. What is the best decision?',[['Aceitar tudo porque o aplicativo é gratuito','Accept everything because the app is free'],['Negar permissões sem relação com a função e considerar outro aplicativo','Deny permissions unrelated to its function and consider another app'],['Compartilhar também a senha do celular','Share the phone password too']],1,['Permissões devem corresponder à função. Limitar acesso desnecessário reduz exposição de dados.','Permissions should match the function. Limiting unnecessary access reduces data exposure.'],['Para iluminar a tela, o aplicativo precisa dos seus contatos?','Does the app need your contacts to light up the screen?']),
 q('O celular recebeu uma atualização de segurança. Como proceder?','Your phone received a security update. What should you do?',[['Instalar pelo sistema e manter os aplicativos atualizados','Install through the system and keep apps updated'],['Baixar uma atualização enviada por SMS','Download an update sent by SMS'],['Desativar atualizações permanentemente','Permanently disable updates']],0,['Use o mecanismo oficial do sistema e da loja. Atualizações corrigem problemas conhecidos.','Use the official system and store mechanisms. Updates fix known issues.'],['Confie no canal de atualização do próprio dispositivo.','Trust the device’s own update channel.']),
 q('Qual configuração protege melhor um celular perdido?','Which setting best protects a lost phone?',[['Tela sempre desbloqueada','A permanently unlocked screen'],['Código de desbloqueio anotado na capa','An unlock code written on the case'],['Bloqueio de tela forte, bloqueio automático e recursos de localização configurados','A strong screen lock, automatic locking and configured locating features']],2,['O bloqueio protege o acesso imediato. Recursos de localização e bloqueio remoto ajudam se estiverem configurados antes da perda.','A lock protects immediate access. Locating and remote locking features help if configured before the loss.'],['Prepare as proteções antes de precisar delas.','Prepare protections before you need them.'])],
 normal:[
 q('Você perdeu um celular corporativo. Qual é a resposta adequada?','You lost a work phone. What is the appropriate response?',[['Esperar alguns dias antes de contar','Wait a few days before telling anyone'],['Publicar a senha nas redes para quem encontrar','Post the password online for whoever finds it'],['Avisar a equipe, usar os recursos autorizados de bloqueio e revisar sessões','Notify the team, use authorized locking features and review sessions']],2,['Reporte prontamente. A equipe avalia bloqueio, sessões e apagamento remoto conforme a política e o contexto.','Report promptly. The team assesses locking, sessions and remote wiping according to policy and context.'],['A perda envolve o dispositivo e as contas acessíveis nele.','Loss involves both the device and its accessible accounts.']),
 q('Um QR code num cartaz abre uma página de login da empresa. O que fazer antes de entrar?','A QR code on a poster opens a company login page. What should you do before signing in?',[['Verificar o endereço e, se houver dúvida, abrir o serviço pelo aplicativo ou endereço conhecido','Check the address and, if uncertain, open the service through the known app or address'],['Confiar porque QR codes não podem ser alterados','Trust it because QR codes cannot be altered'],['Enviar o código MFA ao dono do cartaz','Send the MFA code to the poster’s owner']],0,['QR codes podem apontar para páginas falsas e adesivos podem ser substituídos. Verifique o destino antes de enviar credenciais.','QR codes can point to fake pages and stickers can be replaced. Check the destination before submitting credentials.'],['O QR code é apenas uma forma de transportar um endereço.','A QR code is just a way to carry an address.']),
 q('Uma loja oficial oferece um aplicativo com permissões muito amplas. A loja elimina todos os riscos?','An official store offers an app with very broad permissions. Does the store eliminate all risks?',[['Sim, toda revisão é infalível','Yes, every review is infallible'],['Não; avalie desenvolvedor, necessidade, permissões e manutenção','No; assess developer, need, permissions and maintenance'],['Sim, se houver muitas avaliações','Yes, if it has many reviews']],1,['Lojas confiáveis reduzem alguns riscos, mas não garantem segurança. Continue avaliando permissões e necessidade.','Trusted stores reduce some risks but do not guarantee safety. Continue assessing permissions and need.'],['Uma camada de proteção não é uma garantia absoluta.','A layer of protection is not an absolute guarantee.'])],
 hard:[
 q('Um aplicativo pede permissão de acessibilidade para oferecer cupons. Como avaliar?','An app asks for accessibility permission to offer coupons. How should you assess it?',[['Conceder porque cupons são úteis','Grant it because coupons are useful'],['Conceder se o aplicativo tiver um logo conhecido','Grant it if the app has a familiar logo'],['Questionar a necessidade: essa permissão pode permitir observar ou controlar interações','Question the need: this permission may allow observing or controlling interactions']],2,['Recursos de acessibilidade têm usos legítimos, mas podem dar amplo acesso à interface. Verifique origem e necessidade antes de conceder.','Accessibility features have legitimate uses but may grant broad interface access. Verify source and need before granting them.'],['Compare o poder da permissão com o benefício prometido.','Compare the permission’s power with the promised benefit.']),
 q('O suporte pediu instalar um perfil de gerenciamento por uma mensagem inesperada. Qual é a ação correta?','Support asked you to install a management profile through an unexpected message. What is the correct action?',[['Confirmar a solicitação pelo canal oficial antes de instalar','Confirm the request through the official channel before installing'],['Instalar porque todo perfil melhora a segurança','Install because every profile improves security'],['Desativar o bloqueio do celular primeiro','Disable the phone lock first']],0,['Perfis podem alterar configurações e controles do dispositivo. Confirme pedidos de gerenciamento com a equipe conhecida.','Profiles can change device settings and controls. Confirm management requests with the known team.'],['Gerenciamento do dispositivo exige origem verificada.','Device management requires a verified source.']),
 q('Seu celular está sem sinal e chegaram avisos de troca do SIM e acesso às contas. Qual é o próximo passo?','Your phone has no signal and notices mention SIM replacement and account access. What is the next step?',[['Esperar, pois é apenas falta de bateria','Wait, because it is just a low battery'],['Contatar a operadora por canal conhecido, proteger as contas em dispositivo confiável e avisar a equipe','Contact the carrier through a known channel, secure accounts on a trusted device and notify the team'],['Enviar códigos recebidos a quem telefonar','Send received codes to anyone who calls']],1,['Esse conjunto pode indicar troca fraudulenta de SIM. Verifique com a operadora e proteja contas sem depender do número suspeito.','This combination may indicate fraudulent SIM replacement. Verify with the carrier and secure accounts without relying on the suspect number.'],['Considere o telefone como um meio de recuperação de contas.','Consider the phone as an account recovery method.'])]
};
export const backup:Record<Difficulty,Question[]>={
 easy:[
 q('Seu único backup está em uma pasta no mesmo notebook. Qual problema existe?','Your only backup is in a folder on the same laptop. What is the problem?',[['Uma falha ou infecção pode atingir o original e a cópia','A failure or infection can affect both original and copy'],['Pastas nunca podem ser copiadas','Folders can never be copied'],['Uma cópia no mesmo disco sempre é suficiente','A copy on the same drive is always enough']],0,['Uma cópia no mesmo dispositivo pode ser perdida pelo mesmo evento. Guarde cópias separadas e protegidas.','A copy on the same device can be lost to the same event. Keep separate, protected copies.'],['O que acontece se o notebook inteiro deixar de funcionar?','What happens if the entire laptop stops working?']),
 q('Você sincroniza arquivos na nuvem. Isso sempre equivale a um backup recuperável?','You sync files to the cloud. Is this always equivalent to a recoverable backup?',[['Sim, sincronização nunca replica erros','Yes, syncing never replicates errors'],['Não; exclusões e alterações podem ser sincronizadas. Verifique versões e recuperação','No; deletions and changes may sync. Check versions and recovery'],['Sim, se o ícone da nuvem estiver verde','Yes, if the cloud icon is green']],1,['Sincronização pode replicar exclusões ou dados corrompidos. Avalie histórico, retenção e capacidade de restaurar.','Syncing may replicate deletions or corrupt data. Assess history, retention and restore capability.'],['Sincronizar mudanças e preservar versões são funções diferentes.','Syncing changes and preserving versions are different functions.']),
 q('O aplicativo informa “backup concluído”. O que falta verificar?','The app says “backup complete.” What should you still verify?',[['Somente a cor do ícone','Only the icon’s color'],['Nada; toda cópia é recuperável','Nothing; every copy is recoverable'],['Se é possível restaurar os dados e se eles estão íntegros','Whether data can be restored and remain intact']],2,['Um backup precisa funcionar na recuperação. Testes periódicos verificam acesso, integridade e procedimento.','A backup needs to work during recovery. Periodic tests verify access, integrity and procedure.'],['O objetivo da cópia é recuperar dados quando necessário.','The copy’s purpose is to recover data when needed.'])],
 normal:[
 q('Qual plano está mais próximo da estratégia 3-2-1?','Which plan is closest to the 3-2-1 strategy?',[['Três pastas no mesmo disco','Three folders on the same drive'],['Três cópias em uma única conta sem histórico','Three copies in one account without history'],['Original e duas cópias, em dois tipos de mídia, com uma fora do local','Original plus two copies, on two media types, with one off-site']],2,['3-2-1 busca três cópias no total, dois tipos de mídia e uma fora do local. A proteção contra alterações e incidentes também precisa ser planejada.','3-2-1 aims for three total copies, two media types and one off-site. Protection against changes and incidents must also be planned.'],['Conte cópias, meios de armazenamento e localização.','Count copies, storage media and location.']),
 q('Um disco externo de backup fica conectado o tempo todo ao computador. Qual risco merece atenção?','An external backup drive stays connected to the computer all the time. Which risk deserves attention?',[['Um malware pode alcançar a cópia conectada','Malware may reach the connected copy'],['Discos externos não guardam arquivos','External drives cannot store files'],['Conectar torna os dados automaticamente imutáveis','Connecting makes data automatically immutable']],0,['Cópias acessíveis podem ser alteradas ou criptografadas. Considere proteção offline ou imutável conforme o ambiente.','Accessible copies can be modified or encrypted. Consider offline or immutable protection according to the environment.'],['A cópia ainda está ao alcance do sistema comprometido?','Is the copy still reachable by the compromised system?']),
 q('Para proteger um backup criptografado, o que precisa ser planejado?','What must be planned to protect an encrypted backup?',[['Guardar a chave apenas no computador que será recuperado','Keep the key only on the computer being recovered'],['Proteger as chaves e garantir recuperação autorizada sem depender do dispositivo perdido','Protect keys and ensure authorized recovery without depending on the lost device'],['Publicar a chave junto do arquivo','Publish the key with the file']],1,['Criptografia protege dados, mas perder a chave pode impedir a recuperação. Planeje acesso seguro e teste o processo.','Encryption protects data, but losing the key can prevent recovery. Plan secure access and test the process.'],['A proteção deve permitir recuperação quando o original se perde.','Protection must allow recovery when the original is lost.'])],
 hard:[
 q('O serviço aceita perder no máximo uma hora de dados. Backups a cada 24 horas atendem essa meta?','The service accepts losing at most one hour of data. Do backups every 24 hours meet that goal?',[['Sim, desde que a cópia seja grande','Yes, as long as the copy is large'],['Não; a frequência precisa atender à janela aceitável de perda','No; frequency must meet the acceptable loss window'],['Sim, porque tempo de restauração e perda de dados são iguais','Yes, because restore time and data loss are the same']],1,['RPO define a janela tolerada de perda de dados. Uma cópia diária pode perder muito mais que uma hora. RTO trata do tempo para recuperar o serviço.','RPO defines the tolerated data-loss window. A daily copy may lose much more than one hour. RTO concerns time to recover the service.'],['Separe quantos dados podem ser perdidos de quanto tempo a recuperação leva.','Separate how much data may be lost from how long recovery takes.']),
 q('O teste restaurou arquivos, mas a aplicação não inicia. Qual é a conclusão?','The test restored files, but the application does not start. What is the conclusion?',[['A recuperação foi validada completamente','Recovery has been fully validated'],['Não é necessário testar aplicações','Applications do not need testing'],['O teste revelou dependências ou configurações faltantes; revisar o plano e testar o serviço','The test revealed missing dependencies or settings; review the plan and test the service']],2,['Recuperação deve validar o serviço e suas dependências, não apenas a presença dos arquivos.','Recovery should validate the service and its dependencies, not just the presence of files.'],['Recuperar o serviço exige mais do que copiar arquivos.','Recovering the service requires more than copying files.']),
 q('A conta administrativa principal também pode apagar todos os backups. Como reduzir esse risco?','The primary admin account can also delete all backups. How can you reduce that risk?',[['Separar acessos de backup, limitar privilégios e aplicar proteção contra alterações conforme o plano','Separate backup access, limit privileges and apply change protection according to the plan'],['Reutilizar a mesma senha em todas as contas','Reuse the same password on every account'],['Dar acesso de exclusão a todos para acelerar','Give everyone deletion access to speed things up']],0,['Separação de privilégios e proteção de cópias reduzem a chance de um único comprometimento destruir todas as opções de recuperação.','Privilege separation and copy protection reduce the chance of one compromise destroying all recovery options.'],['Evite um único ponto de controle sobre original e cópias.','Avoid a single control point over originals and copies.'])]
};
const firstTips:Bilingual[][]=[
 [b('Use senhas longas e exclusivas. Um gerenciador ajuda a criar e guardar cada senha.','Use long, unique passwords. A password manager helps create and store each password.'),b('Ative MFA e proteja a recuperação. Passkeys e chaves FIDO2 oferecem resistência a phishing.','Enable MFA and protect recovery. Passkeys and FIDO2 keys offer phishing resistance.')],
 [b('Verifique remetente, domínio e destino. Urgência, segredo e pedidos de credenciais são sinais de alerta.','Check sender, domain and destination. Urgency, secrecy and credential requests are warning signs.'),b('Confirme pedidos inesperados por um canal conhecido. Reporte mensagens suspeitas à equipe responsável.','Verify unexpected requests through a known channel. Report suspicious messages to the responsible team.')],
 [b('HTTPS protege a conexão; não prova a legitimidade do site. Confira o domínio e respeite avisos do navegador.','HTTPS protects the connection; it does not prove site legitimacy. Check the domain and respect browser warnings.'),b('Atualize aplicativos e revise permissões. VPN e modo anônimo não eliminam phishing ou arquivos maliciosos.','Update apps and review permissions. VPN and incognito do not eliminate phishing or malicious files.')]
];
export const modules:Mission[]=[
 ...firstModules.map((m,i)=>({...m,subject:(['password','phishing','browsing'] as Topic[])[i],tips:firstTips[i],quests:[{kind:i===1?'phishing':m.kind,title:[b('Decisões rápidas','Quick decisions'),b('Outra mensagem, novas pistas','Another message, new clues'),b('Fora do escritório','Away from the office')][i]},{kind:i===0?'forge':i===1?'decision':'browser',title:[b('Forja de senhas','Password forge'),b('A próxima ação','The next action'),b('Domínio em foco','Domain in focus')][i]}]})),
 {id:'m4',kind:'privacy',subject:'privacy',label:'04',color:'purple',title:b('Dados que contam histórias','Data that tells stories'),topic:b('Privacidade & dados pessoais','Privacy & personal data'),brief:b('Uma publicação e um relatório podem expor mais do que parece. Ajude a NEXUS a compartilhar apenas o necessário, com as pessoas certas.','A post and a report can reveal more than they seem. Help NEXUS share only what is needed with the right people.'),tips:[b('Compartilhe apenas dados necessários para uma finalidade clara e limite quem pode acessar.','Share only data needed for a clear purpose and limit who can access them.'),b('Remover nomes não garante anonimização. Incidentes e pedidos sobre dados devem seguir o processo de privacidade da organização.','Removing names does not guarantee anonymization. Incidents and data requests should follow the organization’s privacy process.')],quests:[{kind:'privacy',title:b('Antes de publicar','Before posting')},{kind:'privacy',title:b('Acesso na medida certa','Just enough access')}]},
 {id:'m5',kind:'malware',subject:'malware',label:'05',color:'lime',title:b('Alerta no endpoint','Endpoint alert'),topic:b('Malware & resposta inicial','Malware & initial response'),brief:b('Uma estação da NEXUS está se comportando de forma estranha. Identifique os riscos, contenha o impacto e proteja as opções de recuperação.','A NEXUS workstation is behaving strangely. Identify risks, contain impact and protect recovery options.'),tips:[b('Mantenha proteção e atualizações ativas. Não execute anexos, macros ou instaladores inesperados sem verificar a origem.','Keep protection and updates active. Do not run unexpected attachments, macros or installers without verifying their source.'),b('Em suspeita de infecção, contenha o acesso à rede e avise a equipe. Preserve evidências e evite conectar backups ao sistema suspeito.','When infection is suspected, contain network access and notify the team. Preserve evidence and avoid connecting backups to the suspect system.')],quests:[{kind:'malware',title:b('Não execute a armadilha','Do not run the trap')},{kind:'terminal',title:b('Laboratório de contenção','Containment laboratory')}]},
 {id:'m6',kind:'mobile',subject:'mobile',label:'06',color:'cyan',title:b('Defesa no seu bolso','Defense in your pocket'),topic:b('Celular & aplicativos','Phones & apps'),brief:b('O trabalho também acontece no celular. Proteja o dispositivo, revise permissões e prepare uma resposta para perda ou acesso indevido.','Work happens on phones too. Protect the device, review permissions and prepare for loss or unauthorized access.'),tips:[b('Use bloqueio de tela forte, atualizações oficiais e apenas aplicativos necessários. Avalie origem e permissões, mesmo em lojas oficiais.','Use a strong screen lock, official updates and only necessary apps. Assess source and permissions, even in official stores.'),b('Configure localização e bloqueio remoto antes de precisar. Confirme pedidos para instalar perfis ou conceder acessibilidade.','Configure locating and remote locking before you need them. Verify requests to install profiles or grant accessibility access.')],quests:[{kind:'mobile',title:b('Permissão não é obrigação','Permission is not obligation')},{kind:'mobile',title:b('Um dispositivo desapareceu','A device went missing')}]},
 {id:'m7',kind:'backup',subject:'backup',label:'07',color:'purple',title:b('O plano para voltar','The plan to return'),topic:b('Backups & recuperação','Backups & recovery'),brief:b('A defesa precisa de uma segunda chance. Planeje cópias protegidas e prove que a equipe consegue recuperar o serviço quando algo falhar.','Defense needs a second chance. Plan protected copies and prove that the team can recover service when something fails.'),tips:[b('Mantenha cópias separadas e protegidas, incluindo opções fora do local e offline ou imutáveis quando apropriado.','Keep separate, protected copies, including off-site and offline or immutable options where appropriate.'),b('Teste restauração, integridade e dependências. Sincronização não garante recuperação; planeje também acesso às chaves e às contas.','Test restore, integrity and dependencies. Syncing does not guarantee recovery; also plan access to keys and accounts.')],quests:[{kind:'backup',title:b('Uma cópia fora de alcance','An out-of-reach copy')},{kind:'backup',title:b('Teste antes da emergência','Test before the emergency')}]},
 {id:'m8',act:2,kind:'logs',subject:'network',label:'08',color:'cyan',title:b('O caminho da conexão','The connection path'),topic:b('Redes: IP, DNS & portas','Networks: IP, DNS & ports'),brief:b('Um portal aponta para o destino errado. Compare o inventário com os logs e siga as pistas antes de responder ao incidente.','A portal points to the wrong destination. Compare inventory with logs and follow the clues before responding to the incident.'),tips:[b('IP endereça pacotes; DNS consulta registros de nomes; protocolo e porta ajudam a distinguir serviços. Nenhum deles, sozinho, comprova identidade ou confiança.','IP addresses packets; DNS looks up name records; protocol and port help distinguish services. None of them alone proves identity or trust.'),b('Compare origem, destino, horário e mudanças autorizadas. Preserve os logs e separe evidência de hipótese. Não ignore erros de certificado para contornar um problema de rede.','Compare source, destination, time and approved changes. Preserve logs and separate evidence from hypotheses. Do not bypass certificate errors to work around a network issue.')],quests:[{kind:'network-terminal',title:b('Diagnóstico da estação','Workstation diagnostic')},{kind:'network',title:b('Uma porta não conta tudo','A port does not tell everything')}]},
 {id:'m9',act:2,kind:'crypto',subject:'crypto',label:'09',color:'purple',title:b('A chave da mensagem','The message key'),topic:b('Criptografia: cifras, hashes & chaves','Cryptography: ciphers, hashes & keys'),brief:b('A NEXUS precisa entregar um pacote protegido. Recupere a mensagem, confira a integridade e escolha as chaves certas para envio e assinatura.','NEXUS needs to deliver a protected package. Recover the message, check integrity and choose the right keys for sending and signatures.'),tips:[b('Cifragem protege conteúdo; hash compara bytes; assinatura permite verificar conteúdo e origem associada à chave. São objetivos diferentes.','Encryption protects content; a hash compares bytes; a signature verifies content and origin associated with the key. These are different goals.'),b('Proteja chaves secretas e privadas. Confirme a identidade e a finalidade de chaves públicas e a origem de referências de hash.','Protect secret and private keys. Confirm public key identity and purpose, and the origin of hash references.')],quests:[{kind:'crypto-cipher',title:b('Mensagens em rotação','Rotating messages')},{kind:'crypto-keys',title:b('A chave certa','The right key')}]},
 {id:'m10',act:2,kind:'permissions',subject:'permissions',label:'10',color:'lime',title:b('Acesso na medida certa','Just enough access'),topic:b('Sistemas operacionais & permissões','Operating systems & permissions'),brief:b('Um compartilhamento ficou aberto demais. Ajuste os acessos da equipe e avalie quando uma tarefa realmente precisa de administrador.','A shared resource was opened too widely. Set the team’s access and evaluate when a task really needs administrator privileges.'),tips:[b('Conceda o necessário para a tarefa. No modelo Linux, dono, grupo e outros são classes distintas, com leitura, gravação e execução.','Grant what the task requires. In the Linux model, owner, group and others are distinct classes with read, write and execute bits.'),b('No Windows, confira grupos, herança e acesso efetivo. Avalie a origem e a necessidade antes de elevar uma tarefa.','On Windows, check groups, inheritance and effective access. Evaluate source and need before elevating a task.')],quests:[{kind:'permissions-matrix',title:b('A bancada de acessos','The access workbench')},{kind:'permissions-decisions',title:b('Antes de elevar','Before elevating')}]},
 {id:'m11',act:2,kind:'command',subject:'command',label:'11',color:'cyan',title:b('Do comando ao plano','From command to plan'),topic:b('Linha de comando & scripting','Command line & scripting'),brief:b('A equipe precisa consultar registros sem alterá-los e automatizar uma leitura com tratamento de falha. Confira caminhos, argumentos e a ordem das ações.','The team needs to inspect records without changing them and automate reading with error handling. Check paths, arguments and the order of actions.'),tips:[b('Confira a pasta atual, o caminho e os parâmetros. No exemplo PowerShell, LiteralPath pede um nome literal, sem padrões de curingas.','Check the current folder, path and parameters. In the PowerShell example, LiteralPath requests a literal name without wildcard patterns.'),b('Revise a origem do script, limite privilégios e teste sucesso e falha. Uma mensagem de sucesso deve vir após a operação concluída.','Review script origin, limit privileges and test success and failure. A success message should follow a completed operation.')],quests:[{kind:'command-console',title:b('Consultas com contexto','Inspection with context')},{kind:'command-script',title:b('O roteiro da leitura','The reading plan')}]},
 {id:'m12',act:2,kind:'auth',subject:'auth',label:'12',color:'purple',title:b('Quem continua com acesso?','Who still has access?'),topic:b('Autenticação & autorização: sessões, tokens, OAuth','Authentication & authorization: sessions, tokens, OAuth'),brief:b('Você usou um portal em um aparelho compartilhado e conectou um app à agenda. Ajude a NEXUS a encerrar sessões, escolher tokens e limitar permissões sem confundir essas ações.','You used a portal on a shared device and connected an app to the calendar. Help NEXUS end sessions, choose tokens and limit permissions without confusing those actions.'),tips:[b('Sair, expirar sessão e revogar autorização do app têm efeitos diferentes. Confira os controles oficiais e os acessos restantes.','Sign out, session expiry and app authorization revocation have different effects. Check official controls and remaining access.'),b('Access, ID e refresh tokens têm finalidades distintas. Confira destinatário, prazo e escopos; não compartilhe credenciais.','Access, ID and refresh tokens have different purposes. Check audience, lifetime and scopes; do not share credentials.')],quests:[{kind:'auth-session',title:b('Depois de entrar','After signing in')},{kind:'auth-scope',title:b('Permissão com propósito','Permission with purpose') }]},
 {id:'m13',act:2,kind:'email',subject:'email',label:'13',color:'cyan',title:b('De quem veio esse e-mail?','Who sent this email?'),topic:b('Segurança de e-mail: SPF, DKIM e DMARC','Email security: SPF, DKIM and DMARC'),brief:b('Um aviso da escola chegou à sua caixa. Ajude a NEXUS a conferir envelope, assinatura e alinhamento; depois decida se o pedido merece confiança.','A school notice arrived in your inbox. Help NEXUS check envelope, signature and alignment; then decide whether the request deserves trust.'),tips:[b('DMARC passa por SPF aprovado e alinhado OU DKIM aprovado e alinhado. Compare com o From visível.','DMARC passes through passed and aligned SPF OR passed and aligned DKIM. Compare with visible From.'),b('Origem autenticada não garante conteúdo seguro. Confirme pedidos incomuns por um contato conhecido.','Authenticated origin does not guarantee safe content. Confirm unusual requests through a known contact.')],quests:[{kind:'email-routes',title:b('Duas rotas, uma origem','Two routes, one origin')},{kind:'email-policy',title:b('Política com contexto','Policy in context')}]},
 {id:'m14',act:2,kind:'cloud',subject:'cloud',label:'14',color:'purple',title:b('O arquivo saiu da sala','The file left the room'),topic:b('Fundamentos de nuvem & compartilhamento','Cloud fundamentals & sharing'),brief:b('Um boletim da escola ficou aberto demais na nuvem. Ajude a NEXUS a dividir responsabilidades, configurar acesso pela finalidade e conter uma exposição.','A school report was overshared in the cloud. Help NEXUS divide responsibilities, configure purpose-based access and contain exposure.'),tips:[b('Público, identidade, papel e prazo são controles diferentes. Teste quem deveria e quem não deveria entrar.','Audience, identity, role and time are different controls. Test who should and should not enter.'),b('O provedor opera algumas camadas; a equipe cliente ainda cuida dos dados e das configurações sob seu controle.','The provider operates some layers; the customer team still cares for data and settings under its control.')],quests:[{kind:'cloud-share',title:b('Compartilhe na medida certa','Share just enough')},{kind:'cloud-response',title:b('Quem cuida e quem responde?','Who cares and who responds?')}]},
 {id:'m15',act:3,kind:'segment',subject:'segment',label:'15',color:'cyan',title:b('Conversas com limites','Conversations with boundaries'),topic:b('Redes avançadas: segmentação & firewall','Advanced networks: segmentation & firewall'),brief:b('O portal da escola precisa atender visitantes sem abrir o banco de notas. Ajude a NEXUS a escolher os fluxos necessários, entender respostas e investigar tentativas bloqueadas.','The school portal must serve guests without opening the grades database. Help NEXUS choose necessary flows, understand replies and investigate blocked attempts.'),tips:[b('Leia origem, destino, TCP e porta. Zona não é identidade; aplicativo também precisa de autorização.','Read source, destination, TCP and port. A zone is not identity; the app still needs authorization.'),b('Retorno com estado reconhecido não libera conexões novas no sentido inverso.','Recognized stateful return does not allow new reverse connections.')],quests:[{kind:'segment-rules',title:b('Regras por finalidade','Purpose-based rules')},{kind:'segment-state',title:b('Resposta não é entrada livre','Reply is not unrestricted entry')}]},
 {id:'m16',act:3,kind:'investigation',subject:'investigation',label:'16',color:'purple',title:b('As pistas contam uma história','Clues tell a story'),topic:b('Investigação: registros, tempo & evidências','Investigation: logs, time & evidence'),brief:b('Um alerta apareceu no portal da escola. Relacione registros da mesma sessão, organize a linha do tempo e ajude a NEXUS a escrever uma conclusão sem acusar alguém por uma pista isolada.','An alert appeared in the school portal. Connect records from the same session, build a timeline and help NEXUS write a conclusion without accusing someone from one clue.'),tips:[b('Compare sessão, ação e resultado. Horários próximos não provam a mesma atividade.','Compare session, action and outcome. Nearby timestamps do not prove the same activity.'),b('09:01 UTC−03 é 12:01 UTC. Preserve a marca original e confira os relógios.','09:01 UTC−03 is 12:01 UTC. Preserve original timestamps and check clocks.')],quests:[{kind:'investigation-timeline',title:b('A mesma conversa','The same conversation')},{kind:'investigation-findings',title:b('O que sabemos de verdade?','What do we really know?')}]},
 {id:'m17',act:3,kind:'os',subject:'os',label:'17',color:'cyan',title:b('Quem trabalha dentro do sistema?','Who works inside the system?'),topic:b('Internals de SO: processos, serviços & privilégios','OS internals: processes, services & privileges'),brief:b('Um anexo gerou um pedido inesperado no computador da escola. Compare processos, limite os acessos do serviço de relatórios e ajude a NEXUS a investigar pelo contexto.','An attachment triggered an unexpected request on a school computer. Compare processes, limit reporting-service access and help NEXUS investigate context.'),tips:[b('Nome e CPU não provam legitimidade. Compare conta, origem, finalidade e resultado.','Name and CPU do not prove legitimacy. Compare account, origin, purpose and outcome.'),b('Conta dedicada, leitura da entrada e gravação da saída. Negar notas e gravação na entrada também faz parte da tarefa.','Dedicated account, input reading and output writing. Denying grades and input writing is also part of the task.')],quests:[{kind:'os-process',title:b('Além do nome na lista','Beyond the name in the list')},{kind:'os-service',title:b('O serviço e suas portas','The service and its doors')}]},
 {id:'m18',act:3,kind:'applied',subject:'applied',label:'18',color:'purple',title:b('O selo e a confiança','The seal and trust'),topic:b('Criptografia aplicada: assinatura, certificados & chaves','Applied cryptography: signatures, certificates & keys'),brief:b('Um relatório escolar chegou assinado. Ajude a NEXUS a conferir documento, identidade e confiança antes de aceitar o pedido.','A signed school report arrived. Help NEXUS check document, identity and trust before accepting its request.'),tips:[b('HTTPS protege a conexão; assinatura e contexto do certificado do documento exigem verificações próprias.','HTTPS protects the connection; the document signature and certificate context need their own checks.'),b('Trocar a chave não apaga uso indevido anterior. Preserve contexto e siga o procedimento da equipe.','Changing a key does not erase earlier misuse. Preserve context and follow the team’s procedure.')],quests:[{kind:'applied-document',title:b('Confira além do selo','Check beyond the seal')},{kind:'applied-key',title:b('Depois da chave exposta','After key exposure')}]},
 {id:'m19',act:3,kind:'programming',subject:'programming',label:'19',color:'cyan',title:b('O formulário e suas fronteiras','The form and its boundaries'),topic:b('Programação segura: entradas, falhas & registros','Secure programming: input, failures & logs'),brief:b('A inscrição numa oficina recebeu dados inesperados. Ajude a NEXUS a validar o pedido, responder a falhas e guardar pistas úteis sem expor segredos.','Workshop registration received unexpected data. Help NEXUS validate requests, respond to failures and retain useful clues without exposing secrets.'),tips:[b('A tela ajuda; o servidor valida antes de processar. Dado válido não concede permissão.','The screen helps; the server validates before processing. Valid data does not grant permission.'),b('Erro público claro, registro interno controlado e referência comum.','Clear public error, controlled internal log and shared reference.')],quests:[{kind:'programming-contract',title:b('O contrato da inscrição','The registration contract')},{kind:'programming-failure',title:b('Erro útil, segredo protegido','Useful error, protected secret')}]},
 {id:'m20',act:3,kind:'frameworks',subject:'frameworks',label:'20',color:'purple',title:b('Quatro lentes, uma investigação','Four lenses, one investigation'),topic:b('Frameworks: ATT&CK, Kill Chain, NIST & OWASP','Frameworks: ATT&CK, Kill Chain, NIST & OWASP'),brief:b('Um anexo suspeito levantou perguntas na escola. Ajude a NEXUS a escolher referências para comportamentos, fases, risco e segurança do portal, sem inventar evidências.','A suspicious attachment raised questions at school. Help NEXUS choose references for behavior, phases, risk and portal security without inventing evidence.'),tips:[b('Escolha pelo propósito. Referências complementam a análise; não confirmam sozinhas um ataque.','Choose by purpose. References complement analysis; they do not confirm an attack by themselves.'),b('Fatos observados, hipóteses e lacunas precisam aparecer separados no relato.','Observed facts, hypotheses and gaps must be separate in the report.')],quests:[{kind:'frameworks-evidence',title:b('O mapa não é a evidência','The map is not the evidence')},{kind:'frameworks-plan',title:b('Do risco ao teste','From risk to testing')}]},
 {id:'m21',act:3,track:'blue',kind:'blue',subject:'blue',label:'21',color:'cyan',title:b('Plantão: sinais e prioridades','Shift: signals and priorities'),topic:b('Blue Team: monitoramento, SIEM e triagem','Blue Team: monitoring, SIEM and triage'),brief:b('A escola recebe alertas de backup, notas e um sensor silencioso. Ajude a NEXUS a priorizar com contexto e passar o caso sem inventar certezas.','The school receives backup and grade alerts alongside a silent sensor. Help NEXUS prioritize with context and hand off without inventing certainty.'),tips:[b('Quantidade e severidade não substituem contexto e impacto.','Count and severity do not replace context and impact.'),b('Conta não prova autoria; exportação não prova saída de dados.','Account does not prove attribution; export does not prove data leaving.')],quests:[{kind:'blue-context',title:b('Prioridade com contexto','Priority with context')},{kind:'blue-handoff',title:b('Cobertura e passagem de caso','Coverage and handoff')}]},
 {id:'m22',act:3,track:'blue',kind:'detection',subject:'detection',label:'22',color:'cyan',title:b('Uma regra, vários resultados','One rule, several outcomes'),topic:b('Blue Team: regras, ruído e cobertura','Blue Team: rules, noise and coverage'),brief:b('O portal precisa sinalizar exportações inesperadas. Compare fontes, filtros e testes sem confundir menos alertas com mais segurança.','The portal must flag unexpected exports. Compare sources, filters and tests without confusing fewer alerts with better security.'),tips:[b('Leia o objetivo e confira campos antes de criar exceções.','Read the goal and check fields before making exceptions.'),b('Teste o que a regra encontra, perde e não consegue avaliar.','Test what the rule catches, misses and cannot assess.')],quests:[{kind:'detection-scope',title:b('Fonte certa, filtro certo','Right source, right filter')},{kind:'detection-test',title:b('Silêncio não é aprovação','Silence is not a pass')}]},
 {id:'m23',act:3,track:'blue',kind:'traffic',subject:'traffic',label:'23',color:'cyan',title:b('O que a rede realmente mostra','What the network really shows'),topic:b('Blue Team: tráfego e visibilidade','Blue Team: traffic and visibility'),brief:b('Compare conversas, filtros, volume e autorização. Investigue a transferência não explicada sem confundir metadados com conteúdo.','Compare conversations, filters, volume and authorization. Investigate the unexplained transfer without confusing metadata with content.'),tips:[b('Observe as duas direções e a janela antes de interpretar silêncio.','Observe both directions and the window before interpreting silence.'),b('TLS e volume não comprovam finalidade; correlacione o contexto.','TLS and volume do not prove purpose; correlate context.')],quests:[{kind:'traffic-direction',title:b('A resposta escondida','The hidden reply')},{kind:'traffic-context',title:b('Mesmo volume, outro contexto','Same volume, different context')}]},
 {id:'m24',act:3,track:'blue',kind:'incident',subject:'incident',label:'24',color:'cyan',title:b('Conter, preservar, recuperar','Contain, preserve, recover'),topic:b('Blue Team: resposta a incidentes','Blue Team: incident response'),brief:b('Ajude a escola a recuperar o portal sem perder evidências nem manter o acesso indevido.','Help the school recover its portal without losing evidence or retaining unauthorized access.'),tips:[b('Contenção reduz dano; não remove a causa.','Containment reduces harm; it does not remove the cause.'),b('Teste dados, acessos e funções antes do retorno.','Test data, access and functions before return.')],quests:[{kind:'incident-evidence',title:b('Pistas sob pressão','Clues under pressure')},{kind:'incident-recovery',title:b('Voltar com critérios','Return with criteria')}]}
];
export const phishingActions:Record<Difficulty,Question[]>={
 easy:[q('Uma mensagem inesperada pede que você confirme sua senha. Qual é a ação segura?','An unexpected message asks you to confirm your password. What is the safe action?',[['Responder com a senha para agilizar','Reply with the password to save time'],['Não enviar credenciais; abrir o serviço pelo endereço conhecido e reportar a mensagem','Do not send credentials; open the service through the known address and report the message'],['Encaminhar a senha para o grupo','Forward the password to the group']],1,['Verifique a solicitação de forma independente. Não forneça senhas ou códigos por uma mensagem.','Verify the request independently. Do not provide passwords or codes through a message.'],['Use um caminho de acesso que não veio da mensagem.','Use an access path that did not come from the message.']),...decisions.easy.slice(1)],
 normal:[q('Uma mensagem pede pagamento em uma nova conta bancária. Como confirmar?','A message requests payment to a new bank account. How should you verify?',[['Ligar para o contato previamente cadastrado, usando o número conhecido','Call the previously registered contact using the known number'],['Usar apenas o telefone escrito na mensagem','Use only the phone number written in the message'],['Confirmar respondendo ao endereço indicado no pedido','Confirm by replying to the address in the request']],0,['Mudanças financeiras precisam de verificação independente. Um canal fornecido no próprio pedido pode pertencer a quem tenta enganar você.','Financial changes need independent verification. A channel supplied in the request may belong to whoever is trying to deceive you.'],['Verifique por um canal que já existia antes do pedido.','Verify through a channel that existed before the request.']),...decisions.normal.slice(1)],
 hard:[q('A mensagem veio do endereço correto de um parceiro e continua uma conversa antiga. Isso garante legitimidade?','The message came from a partner’s correct address and continues an old conversation. Does that guarantee legitimacy?',[['Sim, conversas antigas são sempre confiáveis','Yes, old conversations are always trustworthy'],['Sim, se houver assinatura corporativa','Yes, if it has a corporate signature'],['Não; a conta pode estar comprometida. Confirme mudanças sensíveis por canal independente','No; the account may be compromised. Verify sensitive changes through an independent channel']],2,['Uma conta legítima pode ser comprometida. Contexto e endereço corretos não dispensam verificação de solicitações sensíveis.','A legitimate account can be compromised. Correct context and address do not remove the need to verify sensitive requests.'],['Avalie a ação solicitada, além da aparência da mensagem.','Assess the requested action, not just the message’s appearance.']),...decisions.hard.slice(1)]
};
const banks:Record<Topic,Record<Difficulty,Question[]>>={password:decisions,phishing:phishingActions,browsing,privacy,malware,mobile,backup,network:networkQuestions,crypto:cryptoQuestions,permissions:permissionQuestions,command:commandQuestions,auth:authQuestions,email:emailQuestions,cloud:cloudQuestions,segment:segmentQuestions,investigation:investigationQuestions,os:osQuestions,applied:appliedQuestions,programming:programmingQuestions,frameworks:frameworkQuestions,blue:blueQuestions,detection:detectionQuestions,traffic:trafficQuestions,incident:incidentQuestions};
export function questionsFor(id:string,difficulty:Difficulty):Question[]{
 if(id==='placement')return modules.filter(m=>(m.act||1)===1).map(m=>banks[m.subject].easy[0]);
 const number=Number(id.match(/^[ms](\d+)/)?.[1]||1);const mission=modules[number-1]||modules[0];const bank=banks[mission.subject][difficulty];
 if(id.startsWith('s'))return id.endsWith('b')?[bank[1],bank[2]]:[bank[0],bank[1]];
 return bank;
}
